(()=>{const n=document.querySelector(".lin-progress-track span"),e=document.querySelector(".lin-progress-value");if(!n||!e)return;const t=()=>{const s=document.documentElement.scrollHeight-window.innerHeight,t=s>0?Math.min(100,Math.max(0,window.scrollY/s*100)):100;n.style.width=`${t}%`,e.value=`${Math.round(t)}%`,e.textContent=`${Math.round(t)}%`};window.addEventListener("scroll",t,{passive:!0}),window.addEventListener("resize",t),t()})()